const $=s=>document.querySelector(s);const intro=$('#intro'),phone=$('#phone'),lock=$('#lock'),chat=$('#chat'),messages=$('#messages'),typing=$('.typing'),cameraView=$('#cameraView'),callView=$('#callView'),photoView=$('#photoView'),endingView=$('#endingView'),ambience=$('#ambience'),voice=$('#noorVoice');let step=0,trust=0,answered=false;const pause=ms=>new Promise(r=>setTimeout(r,ms));function show(el){el.classList.remove('hidden')}function hide(el){el.classList.add('hidden')}function bubble(text,who='noor',photo=false){const d=document.createElement('div');d.className=`msg ${who}${photo?' photo':''}`;if(photo)d.innerHTML='<img src="./assets/phone-photo.jpg"><span class="stamp">03:18</span>';else d.innerHTML=text+'<span class="stamp">03:17</span>';messages.appendChild(d);messages.scrollTop=messages.scrollHeight}async function noor(text,delay=900){show(typing);await pause(delay);hide(typing);bubble(text);if(step===1){voice.currentTime=0;voice.play().catch(()=>{})}}async function beginChat(){hide(lock);show(chat);step=1;await noor('أخيراً فتحت الهاتف.');await noor('كنت أكتب لك من ساعة… لماذا لا ترد؟');await noor('لا تستخدم الكاميرا الآن. أعدك أن هذا مهم.')}function send(text){if(!text.trim())return;bubble(text,'me');$('#reply').value='';trust++;if(step===1){step=2;setTimeout(()=>sequenceTwo(),500)}}async function sequenceTwo(){await noor('قلت لك لا تفتحها.');await noor('اسمع… هل أنت وحدك في الغرفة؟');await noor('هناك شخص واقف خلفك الآن. لا تلتفت. افتح الكاميرا فقط.')}function openCamera(){hide(chat);show(cameraView);setTimeout(()=>$('#cameraFrame')?.classList.add('active'),250);document.querySelector('.camera-frame').classList.add('active')}function closeCamera(){hide(cameraView);show(chat)}async function captured(){document.querySelector('.camera-frame').classList.add('active');await pause(900);hide(cameraView);show(photoView);trust+=2}async function callNoor(){hide(chat);show(callView);$('#callStatus').textContent='تتصل...';await pause(1800);$('#callStatus').textContent='نور تتنفس';show($('#answer'));}async function answerCall(){answered=true;hide($('#answer'));show($('#hang'));$('#callStatus').textContent='اتصال مفتوح';await pause(900);voice.currentTime=0;voice.play().catch(()=>{});setTimeout(()=>{$('#callStatus').textContent='[صمت]';},2400)}function finish(){hide(callView);hide(photoView);hide(cameraView);hide(chat);show(endingView);$('#endingTitle').textContent=trust>=3?'هي خلفك':'لم تكن وحدك';$('#endingCopy').textContent=trust>=3?'تظهر الصورة على الشاشة. نور ليست داخل الهاتف… إنها واقفة خلف كتفك. يصل آخر إشعار: «لا تتحرك».':'ينقطع الاتصال. بعد دقيقة، يضيء الهاتف من تلقاء نفسه: صورة جديدة التُقطت من الكاميرا الأمامية.'}$('#enter').onclick=()=>{hide(intro);show(phone);ambience.volume=.34;ambience.play().catch(()=>{});setTimeout(beginChat,700)};lock.addEventListener('click',beginChat);$('#send').onclick=()=>send($('#reply').value);$('#reply').addEventListener('keydown',e=>{if(e.key==='Enter')send(e.target.value)});$('#camera').onclick=openCamera;$('#closeCamera').onclick=closeCamera;$('#shutter').onclick=captured;$('#gallery').onclick=()=>{hide(cameraView);show(photoView)};$('#closePhoto').onclick=()=>{hide(photoView);show(chat)};$('#call').onclick=callNoor;$('#answer').onclick=answerCall;$('#hang').onclick=finish;$('#back').onclick=()=>{hide(chat);show(lock)};$('#again').onclick=()=>location.reload();$('#flash').onclick=()=>document.querySelector('.camera-frame').classList.toggle('active');setTimeout(()=>{if(!phone.classList.contains('hidden'))document.querySelector('.camera-frame')?.classList.remove('active')},3000);
